    name: { de: "Kalwaria Zebrzydowska", hu: "Kalwaria Zebrzydowska", ro: "Kalwaria Zebrzydowska", en: "Kalwaria Zebrzydowska"},
    image: "/poi-images/poland-kalwaria-zebrzydowska-history-v2.webp",
